// 1) 원문 텍스트
const raw = $input.first().json.output[0].content[0].text;

// 2) ```json ... ``` 코드펜스 제거 + 앞뒤 공백 제거
const cleaned = raw
  .replace(/^```json\s*/i, '')   // 시작의 ```json 제거
  .replace(/^```\s*/i, '')       // 혹시 ```만 있는 경우도 제거
  .replace(/\s*```$/i, '')       // 끝의 ``` 제거
  .trim();

// 3) JSON 파싱
let obj;
try {
  obj = JSON.parse(cleaned);
} catch (e) {
  // 디버깅을 위해 원문/정제문 일부를 에러로 남김
  throw new Error(`JSON.parse failed. cleaned head: ${cleaned.slice(0, 120)} ... ${e.message}`);
}

// 4) 다음 노드에서 $json.Title 등으로 접근 가능
return [{ json: obj }];

